<script setup>import {reactive} from 'vue';import {router} from '@inertiajs/vue3';import Layout from './Layout.vue';defineProps({coupons:Array});const form=reactive({code:'',type:'fixed',value:'',min_subtotal:0,expires_at:'',is_active:true});function create(){router.post('/admin/coupons',form,{onSuccess:()=>Object.assign(form,{code:'',type:'fixed',value:'',min_subtotal:0,expires_at:'',is_active:true})})}</script>
<template><Layout><p class="eyebrow">Promotions</p><h1 class="serif text-5xl font-bold">Coupons</h1><div class="card mt-6"><div class="grid gap-3 sm:grid-cols-2 lg:grid-cols-5"><input v-model="form.code" class="field" placeholder="Code"><select v-model="form.type" class="field"><option value="fixed">Fixed EGP</option><option value="percent">Percent</option></select><input v-model="form.value" class="field" placeholder="Value"><input v-model="form.min_subtotal" class="field" placeholder="Min subtotal"><input v-model="form.expires_at" type="datetime-local" class="field"></div><button @click="create" class="pill dark mt-4">Create coupon</button></div><div class="mt-5 grid gap-3"><article v-for="c in coupons" :key="c.id" class="card flex items-center justify-between"><div><b>{{c.code}}</b><span class="ml-3 opacity-60">{{c.type==='percent'?c.value+'%':c.value+' EGP'}} off</span></div><span>{{c.is_active?'Active':'Hidden'}}</span></article></div></Layout></template>
